// Auto-generated by Vite import.meta.glob at build time.
// Lists all SKILL.md files bundled with the app.

interface SkillModule {
  path: string;
  content: string;
}

const skillFiles = import.meta.glob<string>('../.skills/**/SKILL.md', {
  query: '?raw',
  import: 'default',
  eager: true,
});

export const skillModules: SkillModule[] = Object.entries(skillFiles).map(([path, content]) => ({
  path,
  content: content as string,
}));
